      "content": "/**\n * dsh-paper-agent-skills — bundled skill provider for DeepSeek Harness.\n *\n * Registers the three SKILL.md bundles shipped in `skills/` on `ctx.skills`,\n * so the model-facing skill catalog can list and load them on demand. Each\n * skill keeps its own directory as its resource base, so references and\n * `scripts/` resolve relative to the installed package.\n *\n * @module dsh-paper-agent-skills\n */\nimport { readFile } from 'node:fs/promises'\nimport { fileURLToPath } from 'node:url'\n\n/** Skill provider name; must be unique per host. */\nconst PROVIDER_NAME = 'paper-agent-skills'\n\n/**\n * Standard precedence rank for packaged skill providers. A packaged skill is\n * outranked by workspace project skills (100/200) and user skills (400/500)\n * that share its name, which is the intended override order.\n */\nconst BUNDLED_SKILL_RANK = 600\n\n/** Directories under `skills/`, one per skill, in catalog order. */\nconst SKILL_NAMES = ['academic-paper-writing', 'presentation-slides', 'rebuttal-writing']\n\n/** Absolute skill directory (the skill's resource base). */\nconst skillDir = (name) => fileURLToPath(new URL(`../skills/${name}/`, import.meta.url))\n\n/** Location of a skill's SKILL.md. */\nconst skillFile = (name) => new URL(`../skills/${name}/SKILL.md`, import.meta.url)\n\n/**\n * Split YAML frontmatter from a SKILL.md body. Only top-level `key: value`\n * lines are read, which is all the skill catalog needs (name, description);\n * nested metadata is left untouched and the body is returned trimmed.\n * @param raw - complete SKILL.md text.\n * @returns parsed top-level fields and the instruction body.\n */\nfunction parseFrontmatter(raw) {\n  const text = raw.replace(/^\\uFEFF/, '')\n  if (!text.startsWith('---')) return { data: {}, body: text.trim() }\n  const end = text.indexOf('\\n---', 3)\n  if (end === -1) return { data: {}, body: text.trim() }\n  const head = text.slice(3, end)\n  const body = text.slice(end + 4).trim()\n  const data = {}\n  for (const line of head.split(/\\r?\\n/)) {\n    if (line.length === 0 || /^[ \\t#]/.test(line)) continue\n    const match = /^([A-Za-z0-9_-]+):\\s*(.*)$/.exec(line)\n    if (match === null) continue\n    let value = match[2].trim()\n    const quoted =\n      (value.startsWith(\"'\") && value.endsWith(\"'\")) || (value.startsWith('\"') && value.endsWith('\"'))\n    if (quoted && value.length >= 2) value = value.slice(1, -1)\n    data[match[1]] = value\n  }\n  return { data, body }\n}\n\n/**\n * Read one skill's catalog metadata and body.\n * @param name - directory name under `skills/`.\n * @returns the skill name, description, and instruction body.\n */\nasync function readSkill(name) {\n  const { data, body } = parseFrontmatter(await readFile(skillFile(name), 'utf8'))\n  return {\n    name: data.name ?? name,\n    description: data.description ?? '',\n    content: body,\n  }\n}\n\n/**\n * Build one provider catalog candidate. Summaries are cheap and discovery\n * caching is the registry's job, so the definition is rebuilt on load.\n * @param skill - metadata read from SKILL.md.\n * @returns a catalog candidate carrying its resource base and rank.\n */\nfunction candidateFor(skill) {\n  return {\n    name: skill.name,\n    description: skill.description,\n    invocation: { modelInvocable: true, userInvocable: true },\n    provider: PROVIDER_NAME,\n    source: 'bundled',\n    resourceBase: { kind: 'directory', path: skillDir(skill.name) },\n    rank: BUNDLED_SKILL_RANK,\n    locator: skill.name,\n  }\n}\n\n/** Provider registered on `ctx.skills`. */\nconst provider = {\n  name: PROVIDER_NAME,\n  async list() {\n    const skills = await Promise.all(SKILL_NAMES.map(readSkill))\n    return skills.map(candidateFor)\n  },\n  async get(candidate) {\n    const skill = await readSkill(candidate.locator ?? candidate.name)\n    return {\n      name: skill.name,\n      description: skill.description,\n      invocation: { modelInvocable: true, userInvocable: true },\n      provider: PROVIDER_NAME,\n      source: 'bundled',\n      resourceBase: { kind: 'directory', path: skillDir(skill.name) },\n      content: skill.content,\n    }\n  },\n}\n\n/** Cordis plugin name. */\nexport const name = 'paper-agent-skills'\n\n/** Service required by the bundled provider. */\nexport const inject = ['skills']\n\n/** Register the Paper-Agent skill provider on `ctx.skills`. */\nexport function apply(ctx) {\n  ctx.skills.registerProvider(() => provider)\n}\n"
